    if(!media.length){$('#mediaStatus').textContent='No se encontraron fotografías en la selección.';return;}
    const english=window.AgendaI18n?.language==='en';$('#mediaStatus').textContent=`${media.length} ${media.length===1?(english?'photo selected':'fotografía seleccionada'):(english?'photos selected':'fotografías seleccionadas')} · ${english?'Only visible on this device.':'Solo se visualizan en este dispositivo.'}`;
