  function photoWords(){return window.AgendaI18n?.language==='en'?{photos:'photos',found:'indexed',loaded:'cached',pending:'pending',scanning:'Checking folder changes…',remembered:'Folder remembered on this device',temporary:'Temporary folder access',new:'new',changed:'updated',missing:'originals unavailable'}:{photos:'fotografías',found:'indexadas',loaded:'en caché',pending:'pendientes',scanning:'Comprobando cambios…',remembered:'Carpeta recordada en este dispositivo',temporary:'Acceso temporal a la carpeta',new:'nuevas',changed:'actualizadas',missing:'originales no disponibles'};}
