  function beginPhotoGallery({handle=null,persisted=false,folderId='',clear=true,scanning=false}={}){if(clear)clearMedia();else releasePhotoUrls();photoFolderHandle=handle;photoFolderPersisted=persisted;photoIndexFolderId=folderId;photoIndexScanning=scanning;const generation=photoDirectoryGeneration,track=$('#folderGalleryTrack');$('#mediaView').classList.add('directory-mode');$('#mediaGrid').classList.add('hidden');$('#folderGallery').classList.toggle('hidden',view!=='media');$('#clearMediaBtn').classList.remove('hidden');track.onscroll=null;if('IntersectionObserver'in window)photoThumbObserver=new IntersectionObserver(entries=>{const bounds=track.getBoundingClientRect(),center=bounds.left+bounds.width/2;for(const entry of entries){const index=Number(entry.target.dataset.photoIndex);if(entry.isIntersecting){const rect=entry.target.getBoundingClientRect();queuePhotoThumbnail(index,generation,Math.abs(rect.left+rect.width/2-center));}else{cancelPhotoThumbnail(index);if(index!==photoSelectedIndex&&photoThumbUrls.has(index)){URL.revokeObjectURL(photoThumbUrls.get(index));photoThumbUrls.delete(index);entry.target.removeAttribute('src');}}}},{root:track,rootMargin:'0px 2600px',threshold:0.01});else{photoThumbObserver=null;track.onscroll=()=>track.querySelectorAll('[data-photo-index]').forEach(image=>{const r=image.getBoundingClientRect(),b=track.getBoundingClientRect();if(r.right>=b.left-2600&&r.left<=b.right+2600)queuePhotoThumbnail(Number(image.dataset.photoIndex),generation);});}return generation;}
